        int currMin = Integer.MAX_VALUE;
        for (int i = n - 1; i >= 0; i--) {
            currMin = Math.min(currMin, nums[i]);
            suffixMin[i] = currMin;
        }
        int ans = 0, currMax = Integer.MIN_VALUE;
